/**
 * Machine checks the draft gate runs after the model answers, one list per
 * platform, distilled with the rulebooks (apps/launchkit/rulebooks/<platform>.md).
 * kind: max_chars | min_words | max_words | max_count | forbidden_regex |
 * required_prefix; field names a draft field, or "all" for every string field.
 */
/**
 * kind: max_chars | min_words | max_words | max_count | forbidden_regex |
 * required_regex (the field must match) | required_prefix.
 * flags: the regex flags the gate compiles with (default "i", "iu" when the
 * value carries a \u{...} escape). hard: true when a founder cannot post over
 * it, overriding the gate's kind and id defaults. when: the check runs only
 * when another field matches (a venue-scoped title shape).
 */
export type RuleCheck = { id: string; description: string; kind: string; value: string; field: string; flags?: string; hard?: boolean; when?: { field: string; regex: string } };

